using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApprovedTotal()
    {
        var checkout = typeof(ApplicationMarker).Assembly.GetTypes()
            .Where(t => t.Name.Contains("Checkout", StringComparison.Ordinal) || t.Name.Contains("Pricing", StringComparison.Ordinal))
            .ToList();

        Assert.True(checkout.Count > 0, "No checkout/pricing calculation exists; cannot produce payable total 95.00 for Gold with subtotal 100.00.");
    }
}
